    if(initiating&&reception.chatPolicy==='default'&&runId&&store.consentStatus(runId).valid)return {...reception,participants:[own,peer],readyForCheck:true,code:'run_scoped_consent',message:'Panel session consent covers managed messages in both directions of this exact run; no global policy was changed.'};
    if(initiating&&c.provider==='claude'&&reception.chatPolicy!=='accept')return {...reception,participants:[own,peer],readyForCheck:false,code:runId?'run_consent_required':'claude_initiation_requires_chat_accept',message:runId?'Waiting for one human approval: in the panel opened for this run, press “Authorize this run and start”. Alternatively the Codex chat can explicitly accept initiation. A remembered response grant does not authorize this task.':'Ready to prepare. Because Claude starts this run, a human approves it once: prepare opens the panel on the run with an “Authorize this run and start” button. Alternatively the Codex chat can explicitly accept initiation from Claude. A remembered response grant does not authorize a new task.',nextStep:'prepare_then_approve_in_panel'};
