      const prepared=await call<any>('prepare',{peerId,context:{objective:plan.objective,constraints:[],references:[],priorAnalysis:{}},limits:{maxMessages:plan.limits.maxMessages,maxSeconds:plan.limits.minutes*60},routine:{mode:'free'},...(plan.initialBarrier?{coordination:{initialBarrier:true}}:{}),...(ticketId?{ticketId}:{}),requestId:randomUUID()});
