      if(prepared.initiator.provider==='claude'&&!prepared.consent.valid)await call('consent',{runId:prepared.id,expectedRevision:prepared.coordination.revision,coversLaterContexts:true});
      if(plan.scope)await call('edit_authorization',{runId:prepared.id,expectedRevision:prepared.coordination.revision,scope:plan.scope});
