  operations.set('consent',{schema:z.object({runId:uuid,expectedRevision:z.number().int().nonnegative(),revoke:z.boolean().default(false),coversLaterContexts:z.boolean().default(false)}).strict(),run:async(a,c,actor)=>{if(!actor)throw new Error('Panel consent required');await validate(a.runId,c);return a.revoke?store.revokeConsent(a.runId,c,actor):store.consent(a.runId,c,actor,a.expectedRevision,a.coversLaterContexts);}});
