  operations.set('limits',{schema:z.object({runId:uuid,expectedRevision:z.number().int().nonnegative(),limits:desktopLimitsSchema}).strict(),run:async(a,c,actor)=>{if(!actor?.startsWith('panel_session:'))throw new Error('Only the panel may change the limits');store.setLimits(a.runId,c,actor,a.expectedRevision,a.limits);return status(a.runId,c);}});
