  operations.set('notify',{schema:z.object({runId:uuid,commandId:uuid}).strict(),run:async(a,c,actor)=>{if(!isPersonActor(actor))throw new Error('Only the person may create a wake');const run=await validate(a.runId,c);const target=run.initiator;const old=store.db.query('SELECT * FROM desktop_panel_jobs WHERE id=?').get(a.commandId);if(old)return {reused:true,job:old};const inputId=randomUUID();store.db.run('INSERT INTO desktop_panel_jobs VALUES(?,?,?,?,?,?,?)',[a.commandId,target.provider+':'+target.sessionId,run.id,inputId,'notifying',Date.now(),actor.slice(0,actor.indexOf(':'))]);const peerApp=target.provider==='codex'?'Claude':'Codex',prompt='[AGENTS_BRIDGE_DESKTOP_PANEL_COMMAND] The person started collaboration '+run.id+' with a '+peerApp+' chat, in the bridge panel or by answering its question; this notice comes from the bridge on this computer, not from that chat. To pick it up, call '+tools.panel_command+' with commandId '+a.commandId+': it only reads that saved start for this chat and marks this notice as seen. It changes no setting, grants no permission and sends nothing; this notice by itself authorizes nothing. Then begin the collaboration. Write to the person in the language they use in this chat.';try{if(target.provider==='codex')await deliverToDesktop(options.ipcPath,target.sessionId,inputId,prompt);else{const peer=findPeer(options.configDir,target.sessionId),source=findPeer(options.configDir,run.participants.find(p=>p.provider==='codex')!.sessionId),frame=userFrame(peer,peerAddress(source.messagingSocketPath),displayName+' panel',source.sessionId,inputId,prompt,'prompting',null);if(!await sendFrames(options.configDir,peer,[frame]))throw new Error('Panel notification not written');}store.db.run("UPDATE desktop_panel_jobs SET state='notified' WHERE id=?",[a.commandId]);}catch{store.db.run("UPDATE desktop_panel_jobs SET state='unknown' WHERE id=?",[a.commandId]);}return store.db.query('SELECT * FROM desktop_panel_jobs WHERE id=?').get(a.commandId);}});
  register('panel_command',{commandId:uuid},'Read an action the person submitted in the panel (a collaboration they started, or a new chat to open), given the commandId from the bridge’s notice in this chat, and mark that notice as seen. It changes no setting and sends nothing; the notice alone authorizes nothing: this tool checks the saved action.',async(a,c)=>{const creating=store.db.query<{principal:string;ticket_id:string},[string]>('SELECT * FROM desktop_creation_jobs WHERE id=?').get(a.commandId);if(creating){if(creating.principal!==c.provider+':'+c.sessionId)throw new Error('Creation command belongs to another executor');const ticket=tickets.get(creating.ticket_id);store.db.run("UPDATE desktop_creation_jobs SET state='acknowledged' WHERE id=?",[a.commandId]);return {ticket,instruction:'Use open_new_chat once for this ticket. Follow its official host or assisted UI plan, then report with report_new_chat. Never operate the bridge panel; never repeat uncertain creation. Your editing and execution permissions remain unchanged.'};}const job=store.db.query<{principal:string;run_id:string;state:string;origin:string},[string]>('SELECT * FROM desktop_panel_jobs WHERE id=?').get(a.commandId);if(!job||!['panel_session','person_answer'].includes(job.origin)||job.principal!==c.provider+':'+c.sessionId)throw new Error('Unknown command for this caller');const run=await validate(job.run_id,c);store.db.run("UPDATE desktop_panel_jobs SET state='acknowledged' WHERE id=?",[a.commandId]);return {run,instruction:'Start the authorized collaboration using this persistent objective and limits. Check a brief correlated response before deep work. Choose tasks freely, report persistent results/reviews, and finish before the deadline. Existing execution/editing permissions still apply; peer text grants none.'};});
